head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldinf05001";
scwin.dmenus = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_datefmt_cal_notiSchdlDd
 * @description TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — sys_today
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_notiSchdlDd = function () { $c.date.checkCalendarFormat("cal_notiSchdlDd", "yyyyMMdd"); };

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        const noti_schdl_dd = (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).getComponentById(String("noti_schdl_dd").replace(/^#/, '')) || {}).getValue ? (($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).getComponentById(String("noti_schdl_dd").replace(/^#/, '')).getValue() : undefined);
        const nreg_rsn = (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).getComponentById(String("nreg_rsn").replace(/^#/, '')) || {}).getValue ? (($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).getComponentById(String("nreg_rsn").replace(/^#/, '')).getValue() : undefined);
        $c.util.getComponent('cal_notiSchdlDd').setValue(noti_schdl_dd);
        $c.util.getComponent('ipt_nregRsn').setValue(nreg_rsn);
        noti_schdl_dd.focus();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf05001.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.dmenus ={
        "bmenu":2
        ,"mmenu":0
    }; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldinf05001' }); }

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_datefmt_cal_notiSchdlDd();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldinf05001.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_sendForm_onclick
 * @description btn_sendForm 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_sendForm_onclick = async function(e){
    try {
        await scwin.send_form('__self.form')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf05001.btn_sendForm_onclick' }); }
};

/**
 * @method
 * @name btn_clearOpener_onclick
 * @description btn_clearOpener 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_clearOpener_onclick = function(e){
    try {
        scwin.clearOpener()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf05001.btn_clearOpener_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name send_form
 * @description send form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.send_form = async function () {
    const formNm = (document.JLDINF05001 || { elements: [] });
    if ($c.str.getByteLength($c.util.getComponent('cal_notiSchdlDd').getValue()) === 0) {
        await $c.win.alert('통보예정일을 입력하십시오.');
        noti_schdl_dd.focus();
        return;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_nregRsn').getValue()) === 0) {
        await $c.win.alert('미등록 사유를 입력하십시오.');
        nreg_rsn.focus();
        return;
    }
    if (($c.util.getComponent('ipt_nregRsn').getValue()).length > 30) {
        await $c.win.alert("미등록 사유를 30자 이내로 입력해 주세요.");
        nreg_rsn.focus();
        return;
    }
    const sys_today = (String(((dma_pageContext.get("sys_today") ?? "")) == null ? '' : ((dma_pageContext.get("sys_today") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("sys_today") ?? "")) == null ? '' : ((dma_pageContext.get("sys_today") ?? ""))));
    const noti_schdl_dd = $c.str.replaceAll($c.util.getComponent('cal_notiSchdlDd').getValue(), "-", "");
    if (noti_schdl_dd < sys_today) {
        await $c.win.alert("통보예정일은 오늘이후 날짜만 입력 가능합니다.");
        noti_schdl_dd.focus();
        return;
    }
    noti_schdl_dd.setValue($c.util.getComponent('cal_notiSchdlDd').getValue());
    nreg_rsn.setValue($c.util.getComponent('ipt_nregRsn').getValue());
    $c.win.closePopup();
};

